/* ------------------------------- DISCO (cambiar por animación) ------------------------------- */

static void drawArc(int cx, int cy, int r, int startDeg, int spanDeg)
{
  const int step = 8;
  int px = cx + (int)roundf(r * cosf(startDeg * DEG2RAD));
  int py = cy + (int)roundf(r * sinf(startDeg * DEG2RAD));
  
  for (int d = step; d <= spanDeg; d += step) {
    float rad = (startDeg + d) * DEG2RAD;
    int x = cx + (int)roundf(r * cosf(rad));
    int y = cy + (int)roundf(r * sinf(rad));
    u8g2_DrawLine(&u8g2, px, py, x, y);
    px = x;
    py = y;
  }
}

static void drawSpinningDisc(uint16_t ang)
{
    u8g2_DrawCircle(&u8g2, DISC_CX, DISC_CY, 24, U8G2_DRAW_ALL);
    u8g2_DrawCircle(&u8g2, DISC_CX, DISC_CY, 10, U8G2_DRAW_ALL);

    // Reflejos
    drawArc(DISC_CX, DISC_CY, 20, ang,       50);
    drawArc(DISC_CX, DISC_CY, 15, ang + 180, 30);

    // Agujero central
    u8g2_SetDrawColor(&u8g2, 0);
    u8g2_DrawDisc(&u8g2, DISC_CX, DISC_CY, 3, U8G2_DRAW_ALL);
    u8g2_SetDrawColor(&u8g2, 1);
    u8g2_DrawPixel(&u8g2, DISC_CX, DISC_CY);
}

static uint8_t centrar(const char *texto)
{
    uint16_t ancho = u8g2_GetStrWidth(&u8g2, texto);
    return (ancho >= DISPLAY_WIDTH) ? 0 : (DISPLAY_WIDTH - ancho) / 2;
}

/* ------------------------------- PANTALLAS ------------------------------- */
static void drawInitScreen(void)
{
  u8g2_DrawXBMP(&u8g2, 48, 28, 32, 32, animation_play_load_32_32_14f_frames[animFrame]);
  
  u8g2_SetFont(&u8g2, u8g2_font_t0_22_tr);
  u8g2_DrawStr(&u8g2, 9, 22, "TOCADISCOS");
}

