{
  u8g2_SetFont(&u8g2, u8g2_font_t0_14_tr);
  u8g2_DrawStr(&u8g2, 19, 22, "Sistema listo");
  u8g2_DrawStr(&u8g2, 15, 53, "Apoye un disco");
}

static void drawPlayingScreen(void)
{
    u8g2_SetFont(&u8g2, u8g2_font_t0_14_tr);
    u8g2_DrawTriangle(&u8g2, 2, 2, 2, 10, 8, 6);
    u8g2_DrawStr(&u8g2, 13, 10, "REPRODUCIENDO");

    u8g2_SetClipWindow(&u8g2, 0, 0, 75, 63);

    u8g2_SetFont(&u8g2, u8g2_font_5x8_tf);
    u8g2_DrawStr(&u8g2, 2, 30, titulo);
    u8g2_DrawStr(&u8g2, 2, 50, artista);

    u8g2_SetMaxClipWindow(&u8g2);

    // Disco
    drawSpinningDisc(angle);
}

static void drawTrackEndScreen(void)//CALCULAR POSICION
{
    u8g2_SetFont(&u8g2, u8g2_font_t0_14_tr);
    u8g2_DrawStr(&u8g2, 8, 22, "Pista finalizada");

    u8g2_SetFont(&u8g2, u8g2_font_5x8_tr);
    u8g2_DrawStr(&u8g2, centrar(titulo), 47, titulo);
    
    char cantante[32];
    snprintf(cantante, sizeof(cantante), "de %s", artista);
    u8g2_DrawStr(&u8g2, centrar(cantante), 55, cantante);
}

static void drawUnknownDiscScreen(void)
{
  u8g2_DrawXBMP(&u8g2, 48, 6, 32, 32, animation_warning_blink_32_32_14f_frames[animFrame]);

  u8g2_SetFont(&u8g2, u8g2_font_t0_14_tr);
  u8g2_DrawUTF8(&u8g2, 8, 60, "Disco desconocido");
}

static void drawConfigScreen(void)
{
    u8g2_SetFont(&u8g2, u8g2_font_5x8_tf);
    u8g2_DrawStr(&u8g2, 5, 12, "(futura pantalla de configuración)");
}

static void drawErrorScreen(void)
{
    u8g2_DrawXBMP(&u8g2, 48, 6, 32, 32, animation_wrench_32_32_14f_frames[animFrame]);

    u8g2_SetFont(&u8g2, u8g2_font_t0_14_tf);
    u8g2_DrawUTF8(&u8g2, 8, 60, "Ocurrió un error");
}

/* ------------------------------- FUNCIONES PRIVADAS ------------------------------- */
static void dibujarPantalla(void)
{
    switch (pantalla) {
    case UI_INICIO:        drawInitScreen();        break;
    case UI_ESPERA:        drawWaitingScreen();     break;
    case UI_REPRODUCIENDO: drawPlayingScreen();     break;
    case UI_FIN_PISTA:     drawTrackEndScreen();    break;
    case UI_NO_REGISTRADO: drawUnknownDiscScreen(); break;
    case UI_CONFIG:        drawConfigScreen();      break;
    case UI_ERROR:         drawErrorScreen();       break;
    }
}

static bool_t pantallaAnimada(void)
{
  return (pantalla == UI_REPRODUCIENDO) || (pantalla == UI_ERROR) || (pantalla == UI_INICIO) || (pantalla == UI_NO_REGISTRADO);
}

static void avanzarAnimacion(void)
{
    switch (pantalla) {
    case UI_REPRODUCIENDO: angle     = (angle + ANGLE_STEP) % 360;  break;
    case UI_INICIO:
    case UI_NO_REGISTRADO:
    case UI_ERROR:         animFrame = (animFrame + 1) % ANIMATION_FRAMES; break;
    default: break;
    }
}

/* ------------------------------- FUNCIONES PUBLICAS ------------------------------- */
void displayInit(void)
{
    oledInit(&u8g2);
    pantalla = UI_INICIO;
    sucia = TRUE;
    frameEnCurso = FALSE;
}

void uiMostrar(uiPantalla_t p)
{
    pantalla     = p;
    angle        = 0;           /* la animacion arranca desde el principio    */
    frameEnCurso = FALSE;       /* abandona el cuadro en curso, si lo habia   */
    sucia        = TRUE;
  }
  
void tareaPantalla(void) {
    if (!frameEnCurso) {
        if (pantallaAnimada()) {
            avanzarAnimacion();
        } else if (!sucia) {
            return;
        }
        sucia = FALSE;
        u8g2_FirstPage(&u8g2);
        frameEnCurso = TRUE;
    }

    dibujarPantalla();
    if (!u8g2_NextPage(&u8g2)) {
        frameEnCurso = FALSE;
    }
}
